#!/usr/bin/env python3
"""Run from project root: python3 fix_dup.py"""
import base64, os, sys
if not os.path.exists("app"):
    print("ERROR: run from project root"); sys.exit(1)
content = base64.b64decode("").decode("utf-8")
os.makedirs("lib/vos", exist_ok=True)
open("lib/vos/commands.ts", "w", encoding="utf-8", newline="\n").write(content)
print(f"WRITTEN lib/vos/commands.ts ({len(content.splitlines())} lines)")
print("Run: npm run build && git add lib/vos/commands.ts && git commit -m \"fix: remove duplicate loadUserStore declaration\" && git push origin main")
